import re, json, os

DIR = os.path.dirname(os.path.abspath(__file__))
STORES = ["akiyama-ekimae","enokido","kanamachi","kitasenju","mikawashima","rousai","sakasai","usui","yakuendai"]

def load(slug):
    with open(os.path.join(DIR, slug+".html"), encoding="utf-8", errors="replace") as f:
        return f.read()

def strip_tags(s):
    s = re.sub(r'<[^>]+>', '', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s

def get_all(pattern, html, flags=re.I|re.S):
    return re.findall(pattern, html, flags)

def get_title(html):
    m = re.search(r'<title>(.*?)</title>', html, re.I|re.S)
    return strip_tags(m.group(1)) if m else None

def get_meta(html, name):
    m = re.search(r'<meta[^>]+name=["\']'+name+r'["\'][^>]+content=["\'](.*?)["\']', html, re.I|re.S)
    if not m:
        m = re.search(r'<meta[^>]+content=["\'](.*?)["\'][^>]+name=["\']'+name+r'["\']', html, re.I|re.S)
    return m.group(1) if m else None

def get_og(html, prop):
    m = re.search(r'<meta[^>]+property=["\']og:'+prop+r'["\'][^>]+content=["\'](.*?)["\']', html, re.I|re.S)
    if not m:
        m = re.search(r'<meta[^>]+content=["\'](.*?)["\'][^>]+property=["\']og:'+prop+r'["\']', html, re.I|re.S)
    return m.group(1) if m else None

def get_canonical(html):
    m = re.search(r'<link[^>]+rel=["\']canonical["\'][^>]+href=["\'](.*?)["\']', html, re.I|re.S)
    return m.group(1) if m else None

def get_headings(html, level):
    tags = get_all(r'<h'+str(level)+r'\b[^>]*>(.*?)</h'+str(level)+r'>', html)
    return [strip_tags(t) for t in tags]

def get_heading_sequence(html):
    tags = get_all(r'<(h[1-6])\b[^>]*>(.*?)</\1>', html)
    return [(t[0], strip_tags(t[1])) for t in tags]

def get_tel_links(html):
    return sorted(set(get_all(r'href=["\'](tel:[^"\']+)["\']', html)))

def get_line_links(html):
    return sorted(set([u for u in get_all(r'href=["\'](https?://[^"\']*line[^"\']*)["\']', html) ]))

def get_ext_links_no_blank(html):
    # find all <a> tags with href to external domain not containing target=_blank
    anchors = get_all(r'<a\b([^>]*)>', html)
    bad = []
    for a in anchors:
        hrefm = re.search(r'href=["\']([^"\']+)["\']', a)
        if not hrefm: continue
        href = hrefm.group(1)
        if href.startswith('http') and 'td-group.test-page.site' not in href:
            if 'target=' not in a or 'target="_blank"' not in a.replace("'", '"'):
                bad.append(href)
    return bad

def get_imgs(html):
    imgs = get_all(r'<img\b([^>]*)>', html)
    result = []
    for i in imgs:
        srcm = re.search(r'src=["\']([^"\']+)["\']', i)
        altm = re.search(r'alt=["\']([^"\']*)["\']', i)
        result.append({
            'src': srcm.group(1) if srcm else None,
            'alt': altm.group(1) if altm else None,
            'has_alt_attr': altm is not None,
            'lazy': 'loading="lazy"' in i or "loading='lazy'" in i,
            'has_wh': ('width=' in i and 'height=' in i)
        })
    return result

def get_jsonld(html):
    blocks = get_all(r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>', html)
    parsed = []
    for b in blocks:
        try:
            parsed.append(json.loads(b))
        except Exception as e:
            parsed.append({"_parse_error": str(e), "_raw": b[:300]})
    return parsed

def find_js_pseudo_links(html):
    # onclick-based navigation without href, or href="#" or href="javascript:"
    anchors = get_all(r'<a\b([^>]*)>', html)
    bad = []
    for a in anchors:
        hrefm = re.search(r'href=["\']([^"\']*)["\']', a)
        href = hrefm.group(1) if hrefm else None
        if href in ('#', '', None) or (href and href.startswith('javascript:')):
            if 'onclick' in a:
                bad.append(a[:150])
    return bad

data = {}
for s in STORES:
    html = load(s)
    d = {}
    d['title'] = get_title(html)
    d['description'] = get_meta(html, 'description')
    d['og_title'] = get_og(html, 'title')
    d['og_description'] = get_og(html, 'description')
    d['og_image'] = get_og(html, 'image')
    d['og_url'] = get_og(html, 'url')
    d['canonical'] = get_canonical(html)
    d['h1'] = get_headings(html, 1)
    d['h2'] = get_headings(html, 2)
    d['h3'] = get_headings(html, 3)
    d['heading_seq'] = get_heading_sequence(html)
    d['tel_links'] = get_tel_links(html)
    d['line_links'] = get_line_links(html)
    d['ext_links_no_blank'] = get_ext_links_no_blank(html)
    d['imgs'] = get_imgs(html)
    d['jsonld'] = get_jsonld(html)
    d['js_pseudo_links'] = find_js_pseudo_links(html)
    d['html_len'] = len(html)
    data[s] = d

with open(os.path.join(DIR, 'parsed.json'), 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

print("done")

